{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "AZD0837, a structurally close oral prodrug containing a benzyl amidoxime and proline amide, has an absolute bioavailability of 22–52% in humans, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Perindopril, an ethyl ester prodrug, has an absolute oral bioavailability of about 75% in humans, supporting the high-F pattern expected for the query's ester prodrug motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Perindoprilat, the active diacid metabolite of perindopril, has a bioavailability of only 19% ±7% after oral perindopril in young healthy subjects; this is the only affirmative sub-20% anchor, but it applies to the non-prodrug active acid rather than the ester prodrug query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Encainide, despite variable first-pass metabolism, has absolute oral bioavailability values of 20–30% in healthy subjects, providing a threshold-relevant example that F ≥20% is achievable for extensively metabolized drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an ester/amidoxime prodrug; the closest structural analogue AZD0837 has F 22–55%, and ester prodrugs such as perindopril show high F. The only sub-20% evidence is for the active diacid perindoprilat, which is less transferable. Overall, F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "The closest analogue's lower bound is near the 20% threshold, so prodrug conversion and first-pass effects could lower F.",
    "Species- and dose-dependent variability in prodrug hydrolysis is not fully captured by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

